function registryBindingDiffPreview(input={}){
  const afterAll=[input.afterKey,input.afterRedeemerHash,input.afterDatumHash,input.afterWithdrawals,input.afterPrefix,input.afterPostfix].map(v=>String(v??'').trim());
  if(afterAll.every(v=>!v))return `<p class="fine-print">Enter the registration as it would be after the change — the redeemer’s key and minting logic credential, the datum credential, the withdrawals, and the template prefix and postfix — and how the binding checked above changes appears as you type, compared locally between the two versions.</p>`;
  try{
    const before=registryBindingModelInput(input);
    const after=registryBindingModelInput({key:input.afterKey??'',redeemerKind:input.afterRedeemerKind??'script',redeemerHash:input.afterRedeemerHash??'',datumKind:input.afterDatumKind??'script',datumHash:input.afterDatumHash??'',withdrawals:input.afterWithdrawals??'',prefix:input.afterPrefix??'',postfix:input.afterPostfix??''});
    const d=diffRegistryInsertBinding(before,after);
    const short=h=>`<span class="mono">${esc(h.slice(0,8))}…</span>`;
    const credStr=s=>{const i=s.indexOf(':');const kind=s.slice(0,i),hash=s.slice(i+1);return `${esc(kind)} <span class="mono">${esc(hash?hash.slice(0,8)+'…':'(empty)')}</span>`;};
    const labels={'unchanged':['REGISTRY INSERT BINDING UNCHANGED','the change leaves the registration exactly as checked above — the datum names the redeemer’s credential, or not, the template derives the key, or not, and the minting logic is invoked, or not, in both versions'],'became-not-conforming':['BECAME NOT CONFORMING','the after version no longer satisfies a position it satisfied before — the datum no longer names the redeemer’s credential, the template no longer derives the key, or the minting logic is no longer invoked — so the registry validator would refuse a registration the before version allowed'],'became-conforming':['BECAME CONFORMING','the before version broke a position and the after version satisfies them all — the datum names the redeemer’s credential, the template parameterised by it hashes to the key, and its withdraw-zero is invoked'],'still-not-conforming':['STILL NOT CONFORMING — DIFFERENTLY','neither version binds, but a position changed underneath it, so fixing the before version’s failure does not fix the after version’s'],'requirement-changed':['REQUIREMENT CHANGED','the registration binds on both sides, but the expected policy moved — the issuance template parameterised by the redeemer’s credential derives a different policy, and the registration survives, bound under a different derived policy']};
    const pair=labels[d.change];
    const showVal=(field,v)=>field==='status'?(v==='bound'?'bound':'not bound'):field==='expectedPolicyId'?(v===null?'no policy derived':null):(v?'matches':'fails');
    const lines=d.differences.map(x=>x.field==='expectedPolicyId'
      ?`<p class="fine-print"><strong>${esc(x.label)} · DIFFERS</strong> — before: ${x.before===null?'no policy derived':short(x.before)}; after: ${x.after===null?'no policy derived':short(x.after)}.</p>`
      :`<p class="fine-print"><strong>${esc(x.label)} · DIFFERS</strong> — before: ${esc(showVal(x.field,x.before))}; after: ${esc(showVal(x.field,x.after))}.</p>`).join('');
    const listLines=[
      d.keyChanged?`<p class="fine-print"><strong>Key changed</strong> — the redeemer now names a different policy as the key. Reported, never counted: its scored consequence is the policy binding position above.</p>`:'',
      d.mintingLogicChanged?`<p class="fine-print"><strong>Redeemer minting logic changed</strong> — the credential the expected policy is derived from is a different credential. Reported, never counted: it is the input the expected policy and the verdicts are computed from.</p>`:'',
      d.datumMintingLogicChanged?`<p class="fine-print"><strong>Datum minting logic changed</strong> — the new node’s datum names a different credential. Reported, never counted, for the same reason.</p>`:'',
      (d.templatePrefixChanged||d.templatePostfixChanged)?`<p class="fine-print"><strong>Issuance template changed</strong> — the ${d.templatePrefixChanged&&d.templatePostfixChanged?'prefix and postfix':d.templatePrefixChanged?'prefix':'postfix'} bytes differ. Reported, never counted: the template is the other input the expected policy is derived from.</p>`:'',
      d.withdrawalsAdded.length?`<p class="fine-print"><strong>Withdrawals added</strong> — ${d.withdrawalsAdded.map(credStr).join(', ')} (${d.withdrawalCountBefore} before, ${d.withdrawalCountAfter} after). Reported, never counted: they are the causes, the verdict positions above are the consequence.</p>`:'',
      d.withdrawalsRemoved.length?`<p class="fine-print"><strong>Withdrawals removed</strong> — ${d.withdrawalsRemoved.map(credStr).join(', ')} (${d.withdrawalCountBefore} before, ${d.withdrawalCountAfter} after). Reported, never counted, for the same reason.</p>`:'',
    ].join('');
    return `<span class="mini-label">REGISTRY INSERT BINDING IMPACT · LOCAL MODEL · ${pair[0]} · ${d.differences.length} OF 5 POSITIONS DIFFER</span>${listLines}${lines}<p class="fine-print">${pair[1]}. Compared locally between the two modeled versions you entered — PRISM read no reference input and no transaction and registered nothing, and neither version is one. Comparing is not checking or registering: no registration was made against either version. The registry NFT the new node must hold is the outputs family’s position, on both sides alike, and a binding is only as deployment-true as the template bytes entered in each version.</p>`;
  }catch(e){return `<span class="mini-label">REGISTRY INSERT BINDING IMPACT · LOCAL MODEL · NOT COMPARED</span><p class="fine-print">${esc(e.message)}</p>`;}
}
function registryOutputsPreview({key='',prevKey='',policy='',mint='',prevPayment='',prevStake='none',prevRef='none',prevAssets='',newPayment='',newStake='none',newRef='none',newAssets=''}={}){
  const k=(key??'').trim(),pk=(prevKey??'').trim(),rp=(policy??'').trim();
  const all=[k,pk,rp,(mint??'').trim(),(prevPayment??'').trim(),(prevAssets??'').trim(),(newPayment??'').trim(),(newAssets??'').trim()];
  if(all.every(v=>!v))return `<p class="fine-print">Enter a claimed registration’s transaction side — the key being registered, the covering node’s key, the registry policy, the assets minted under that policy, and the two registry-node outputs — and the registry’s five output requirements are judged as you type. The example loaded here conforms.</p>`;
  try{
    const parseMint=text=>(text??'').split(/\n+/).map(x=>x.trim()).filter(Boolean).map(line=>{
      const parts=line.split(/\s+/).filter(Boolean);
      if(parts.length!==2)throw new Error(`Each mint line must name an asset name and a quantity — ${JSON.stringify(line)} given. Use a dash for the empty name.`);
      return {name:parts[0]==='-'?'':parts[0],quantity:parts[1]};
    });
    const parseAssets=text=>(text??'').split(/\n+/).map(x=>x.trim()).filter(Boolean).map(line=>{
      const parts=line.split(/\s+/).filter(Boolean);
      if(parts.length!==3)throw new Error(`Each asset line must name a policy, an asset name, and a quantity — ${JSON.stringify(line)} given. Use a dash for the empty name.`);
      return {policy:parts[0],name:parts[1]==='-'?'':parts[1],quantity:parts[2]};
    });
    const output=(payment,stake,ref,assets)=>({paymentHash:(payment??'').trim(),stakeCredential:stake==='present',referenceScript:ref==='present',assets:parseAssets(assets)});
    const v=checkRegistryInsertOutputs({key:k,prevKey:pk,registryPolicy:rp,minted:parseMint(mint),prevOutput:output(prevPayment,prevStake,prevRef,prevAssets),newOutput:output(newPayment,newStake,newRef,newAssets)});
    const row=(label,ok,detail)=>`<p class="fine-print"><strong>${label} · ${ok?'MATCHES':'FAILS'}</strong> — ${detail}</p>`;
    const head=v.valid?'REGISTRY INSERT OUTPUTS · LOCAL MODEL · CONFORM':'REGISTRY INSERT OUTPUTS · LOCAL MODEL · DO NOT CONFORM';
    const summary=v.valid?`<p class="fine-print"><strong>The claimed outputs conform as the registry requires</strong> — exactly one registry NFT is minted, named by the key; each node output holds its own node’s NFT and nothing else; neither carries a reference script; and both sit at payment-only registry addresses.</p>`:`<p class="fine-print"><strong>The claimed outputs break the positions marked FAILS</strong> — carried into a transaction as claimed, the registry validator would refuse it there.</p>`;
    const nftLine=(which,nodeKey)=>`exactly one asset under the registry policy — the NFT named <span class="mono">${esc(nodeKey===''?'':nodeKey)}</span>${nodeKey===''?' (the empty name — the origin node’s)':''} at quantity 1`;
    return `<span class="mini-label">${head}</span>${summary}`
      +row('Minted registry NFT',v.verdicts.mintedNft,v.verdicts.mintedNft?`the transaction mints ${nftLine('mint',v.key)} under the registry policy <span class="mono">${esc(v.registryPolicy)}</span>`:`the mint under the registry policy must be exactly one asset — the NFT named by the key being registered, at quantity 1 (the spec’s registration point 5; the reference’s validate_mint)`)
      +row('Covering node NFT',v.verdicts.prevNft,v.verdicts.prevNft?`the returned covering node output holds ${nftLine('prev',v.prevKey)}`:`the returned covering node output must hold its own node’s NFT — the asset under the registry policy named by the covering node’s key${v.prevKey===''?' (the empty name — the covering node here is the origin)':''} at quantity 1, and no other asset under that policy`)
      +row('New node NFT',v.verdicts.newNft,v.verdicts.newNft?`the new node output holds ${nftLine('new',v.key)}`:`the new node output must hold the new node’s NFT — the asset under the registry policy named by the key being registered at quantity 1, and no other asset under that policy`)
      +row('Covering node value',v.verdicts.prevExtraValue,v.verdicts.prevExtraValue?`the covering node output carries no asset under any policy but the registry policy — a node’s value is lovelace plus its NFT`:`the covering node output carries an asset under another policy — a registry node’s value carries exactly two policies, lovelace and the registry policy`)
      +row('New node value',v.verdicts.newExtraValue,v.verdicts.newExtraValue?`the new node output carries no asset under any policy but the registry policy — a node’s value is lovelace plus its NFT`:`the new node output carries an asset under another policy — a registry node’s value carries exactly two policies, lovelace and the registry policy`)
      +row('Covering node reference script',v.verdicts.prevNoReferenceScript,v.verdicts.prevNoReferenceScript?`the covering node output carries no reference script`:`the covering node output carries a reference script — neither node output may (the spec’s registration point 6)`)
      +row('New node reference script',v.verdicts.newNoReferenceScript,v.verdicts.newNoReferenceScript?`the new node output carries no reference script`:`the new node output carries a reference script — neither node output may (the spec’s registration point 6)`)
      +row('Covering node address',v.verdicts.prevAddress,v.verdicts.prevAddress?`the covering node output sits at the registry address — its payment credential is the registry script hash and it carries no stake credential`:`a node output’s address must only have payment credentials (the spec’s registration point 7): its payment credential must be the registry script hash itself — the registry script’s mint and spend handlers share one hash — and no stake credential may be present`)
      +row('New node address',v.verdicts.newAddress,v.verdicts.newAddress?`the new node output sits at the registry address — its payment credential is the registry script hash and it carries no stake credential`:`a node output’s address must only have payment credentials (the spec’s registration point 7): its payment credential must be the registry script hash itself — the registry script’s mint and spend handlers share one hash — and no stake credential may be present`)
      +`<p class="fine-print">Checked locally against the modeled mint and outputs entered — PRISM read no transaction and no UTxO and registered nothing. The list mechanics are judged by the insertion planner and verifier above, the datum contents by the datum checker below, and the cryptographic binding by the binding checker above. The new node’s lovelace amount is not judged: the spec recommends the protocol minimum, it does not require it (CIP-113, Programmable token registration).</p>`;
  }catch(e){return `<p class="fine-print">${esc(e.message)}</p>`;}
}
function registryOutputsModelInput({key='',prevKey='',policy='',mint='',prevPayment='',prevStake='none',prevRef='none',prevAssets='',newPayment='',newStake='none',newRef='none',newAssets=''}={}){
  const parseMint=text=>(text??'').split(/\n+/).map(x=>x.trim()).filter(Boolean).map(line=>{
    const parts=line.split(/\s+/).filter(Boolean);
    if(parts.length!==2)throw new Error(`Each mint line must name an asset name and a quantity — ${JSON.stringify(line)} given. Use a dash for the empty name.`);
    return {name:parts[0]==='-'?'':parts[0],quantity:parts[1]};
  });
  const parseAssets=text=>(text??'').split(/\n+/).map(x=>x.trim()).filter(Boolean).map(line=>{
    const parts=line.split(/\s+/).filter(Boolean);
    if(parts.length!==3)throw new Error(`Each asset line must name a policy, an asset name, and a quantity — ${JSON.stringify(line)} given. Use a dash for the empty name.`);
    return {policy:parts[0],name:parts[1]==='-'?'':parts[1],quantity:parts[2]};
  });
  const output=(payment,stake,ref,assets)=>({paymentHash:(payment??'').trim(),stakeCredential:stake==='present',referenceScript:ref==='present',assets:parseAssets(assets)});
  return {key:String(key??'').trim(),prevKey:String(prevKey??'').trim(),registryPolicy:String(policy??'').trim(),minted:parseMint(mint),prevOutput:output(prevPayment,prevStake,prevRef,prevAssets),newOutput:output(newPayment,newStake,newRef,newAssets)};
}
