function globalDispatchModelInput({action='transfer',delegatesText='',withdrawalsText=''}={}){
  const NL=String.fromCharCode(10);
  const credLines=(t,label)=>String(t??'').split(NL).map(x=>x.trim()).filter(Boolean).map(line=>{
    const parts=line.split(/\s+/);
    if(parts.length!==2||!['script','pubkey'].includes(parts[0]))throw new Error(`Each ${label} line must name a credential kind (script or pubkey) and its 28-byte hash \u2014 ${JSON.stringify(line)} given.`);
    return {kind:parts[0],hash:parts[1]};
  });
  const delegates={};
  const names={'transfer':'transfer','third-party':'thirdParty','unfracking':'unfracking'};
  String(delegatesText??'').split(NL).map(x=>x.trim()).filter(Boolean).forEach(line=>{
    const parts=line.split(/\s+/);
    if(parts.length!==3||!(parts[0] in names)||!['script','pubkey'].includes(parts[1]))throw new Error(`Each wiring line must name an action (transfer, third-party, or unfracking), a credential kind (script or pubkey), and its 28-byte hash \u2014 ${JSON.stringify(line)} given.`);
    if(delegates[names[parts[0]]])throw new Error(`The wiring names the ${parts[0]} delegate more than once \u2014 the parameters name one delegate per action.`);
    delegates[names[parts[0]]]={kind:parts[1],hash:parts[2]};
  });
  return {action,delegates,withdrawals:credLines(withdrawalsText,'withdrawal')};
}
