    const labels={'unchanged':['EXECUTION UNCHANGED','the change leaves the execution exactly as checked above \u2014 the same logic credential is required, and it is executed, or not, and the holder authorised, or not, in both versions'],'became-not-conforming':['BECAME NOT CONFORMING','the after version no longer satisfies a requirement it satisfied before \u2014 its logic credential is not executed, or its holder no longer authorises \u2014 so the delegate would refuse an action the before version\u2019s execution allowed'],'became-conforming':['BECAME CONFORMING','the before version broke a requirement and the after version satisfies both \u2014 the logic credential is executed and, for unfracking, the holder authorises'],'still-not-conforming':['STILL NOT CONFORMING \u2014 DIFFERENTLY','neither version conforms, but a position changed underneath it, so fixing the before version\u2019s failure does not fix the after version\u2019s'],'requirement-changed':['REQUIREMENT CHANGED','the execution conforms on both sides, but the logic credential is a different credential \u2014 the script whose withdraw-zero validates the action is no longer the one that validated it before']};
    const pair=labels[d.change];
    const showVal=(field,v)=>field==='status'?(v==='conforming'?'conforming':'not conforming'):field==='logicExecution'?(v?'executed':'not executed'):field==='holderAuthorization'?(v===null?'no verdict (bypassed)':v?'authorised':'not authorised'):null;
    const lines=d.differences.map(x=>`<p class="fine-print"><strong>${esc(x.label)} · DIFFERS</strong> \u2014 before: ${x.field==='logicCredential'?cred(x.before):esc(showVal(x.field,x.before))}; after: ${x.field==='logicCredential'?cred(x.after):esc(showVal(x.field,x.after))}.</p>`).join('');
    const listLines=[
      d.holderCredentialChanged?`<p class="fine-print"><strong>Holder credential changed</strong> \u2014 before: ${cred(d.before.holderCredential)}; after: ${cred(d.after.holderCredential)}. Reported, never counted: for a third-party action the holder is bypassed entirely, and for unfracking the change\u2019s whole consequence already shows in the holder-authorization position above.</p>`:'',
      d.addedWithdrawals.length?`<p class="fine-print"><strong>Withdrawals added</strong> \u2014 ${d.addedWithdrawals.map(cred).join(', ')}.</p>`:'',
      d.removedWithdrawals.length?`<p class="fine-print"><strong>Withdrawals removed</strong> \u2014 ${d.removedWithdrawals.map(cred).join(', ')}.</p>`:'',
      d.addedSigners.length?`<p class="fine-print"><strong>Signers added</strong> \u2014 ${d.addedSigners.map(short).join(', ')}.</p>`:'',
      d.removedSigners.length?`<p class="fine-print"><strong>Signers removed</strong> \u2014 ${d.removedSigners.map(short).join(', ')}.</p>`:'',
    ].join('');
    return `<span class="mini-label">DELEGATE LOGIC EXECUTION IMPACT · LOCAL MODEL · ${pair[0]} · ${d.differences.length} OF 4 POSITIONS DIFFER</span>${listLines}${lines}<p class="fine-print">${pair[1]}. Compared locally between the two modeled versions you entered \u2014 PRISM read no transaction, no registry, and no UTxO, and neither version is one. Comparing is not checking or building: no execution was applied to either version. Whether the RegistryNode the redeemer names actually carries either version\u2019s logic credential is the registry-node checker\u2019s position below, on both sides alike.</p>`;
