function transferProofListPreview(input={}){
  if(!String(input.spentText??'').trim()&&!String(input.mintText??'').trim()&&!String(input.proofsText??'').trim())return `<p class="fine-print">Enter a modeled transfer — the non-lovelace policies in the UTxOs it spends from programmableLogicBase addresses, the policies in its mint, and the policies its proof list proves, in list order — and the list&#8217;s completeness and ordering are judged as you type. The example loaded here conforms.</p>`;
  try{
    const v=checkTransferProofList(transferProofListModelInput(input));
    const short=policy=>`<span class="mono">${esc(policy.slice(0,8))}&#8230;</span>`;
    const src=source=>source==='spent-and-minted'?'spent from a base address and also in the mint — one proof covers both':source==='spent'?'spent from a base address':'in the mint only — validated through the same list as spent tokens';
    const policyLines=v.perPolicy.map(r=>`<p class="fine-print"><strong>Policy ${short(r.policy)} proof · ${r.proven?'PRESENT':'MISSING'}</strong> — ${src(r.source)}${r.proven?', and the claimed list proves it.':', and no proof in the claimed list names it — the delegate would refuse the transfer over an unproven policy.'}</p>`).join('');
    const extraLines=v.completeness.extra.map(policy=>`<p class="fine-print"><strong>Policy ${short(policy)} proof · EXTRA</strong> — the claimed list proves a policy this transfer neither spends from a base address nor mints; the requirement is one proof per touched policy, no more.</p>`).join('');
    const dupLines=v.completeness.duplicates.map(policy=>`<p class="fine-print"><strong>Policy ${short(policy)} proof · DUPLICATED</strong> — the claimed list proves this policy more than once; a policy is proven once, or not at all.</p>`).join('');
    const orderLine=v.ordering.ordered
      ?`<p class="fine-print"><strong>Proof-list ordering · MATCHES</strong> — the claimed list stands in the policies&#8217; lexicographic (byte) order.</p>`
      :`<p class="fine-print"><strong>Proof-list ordering · FAILS</strong> — proof ${v.ordering.firstOutOfOrder+1} does not sort strictly after proof ${v.ordering.firstOutOfOrder}: the list order must match the policies&#8217; lexicographic order, and a duplicate is out of order with itself.</p>`;
    const head=v.valid?'TRANSFER PROOF LIST · LOCAL MODEL · CONFORM':'TRANSFER PROOF LIST · LOCAL MODEL · DO NOT CONFORM';
    const summary=v.valid
      ?`<p class="fine-print"><strong>The claimed proof list is complete and ordered</strong> — the modeled transfer touches ${v.requiredCount} distinct ${v.requiredCount===1?'policy':'policies'} (${v.spentDistinctCount} spent${v.overlapCount?`, ${v.overlapCount} of them also minted`:''}) and the list proves each exactly once, in lexicographic order.</p>`
      :`<p class="fine-print"><strong>The claimed proof list breaks the positions marked MISSING, EXTRA, DUPLICATED, or FAILS</strong> — carried into a transaction as claimed, the transfer delegate would refuse it there.</p>`;
    return `<span class="mini-label">${head}</span>${summary}${policyLines}${extraLines}${dupLines}${orderLine}<p class="fine-print">Judged locally against the modeled spent, mint, and proof lists entered. PRISM read no transaction and no UTxO: which policies a real transaction&#8217;s base UTxOs and mint actually carry are facts about that transaction, not judged here. Whether each listed proof accurately represents its policy&#8217;s registration status is judged by the registry-proof checker below against its modeled reference inputs, and by the proof verifier in the registry panel against its modeled key list; whether a proven-registered token&#8217;s transfer logic executed and each spend was authorised is the authorization checker above; the expected output value is the calculator below.</p>`;
  }catch(e){return `<span class="mini-label">TRANSFER PROOF LIST · LOCAL MODEL · NOT CHECKED</span><p class="fine-print">${esc(e.message)}</p>`;}
}

