function registryProofsPreview({registry='',policies=''}={}){
  const parse=v=>String(v??'').split(/[\s,]+/).map(s=>s.trim()).filter(Boolean);
  const keys=parse(registry),queried=parse(policies);
  if(!keys.length&&!queried.length)return `<p class="fine-print">Enter a modeled registry list and the policies a transfer would touch, and the proof for each appears as you type — planned locally from the list alone, nothing looked up. The example list and policies loaded above show one proof of each kind.</p>`;
  if(!queried.length)return `<p class="fine-print">Enter at least one policy ID to prove against this modeled registry list.</p>`;
  try{const plan=planRegistryProofs(keys,queried);
    const lines=plan.proofs.map((p,i)=>{
      if(p.status==='registered')return `<p class="fine-print"><strong>Proof ${i+1} · REGISTERED · TokenExists</strong> — policy <span class="mono">${esc(p.policy)}</span> is registry node ${p.nodeIndex} in this list: include that node as a reference input, and the token's transfer logic must run in the transaction.</p>`;
      if(p.status==='unregistered')return `<p class="fine-print"><strong>Proof ${i+1} · NOT REGISTERED · TokenDoesNotExist</strong> — covering node ${p.nodeIndex}, key <span class="mono">${esc(p.nodeKey)}</span>, whose next is <span class="mono">${esc(p.nextKey)}</span>: ${esc(p.nodeKey)} &lt; ${esc(p.policy)} &lt; ${esc(p.nextKey)}, so the policy is proved absent and the asset is treated as an ordinary native token that can always leave the base script.</p>`;
      const why=p.reason==='empty-registry'?'the modeled registry is empty, so it contains no covering node':p.reason==='before-first'?'the policy sorts before the first key in this list, so no node in it has a smaller key':'the policy sorts after the last key in this list, so no node in it points past it';
      return `<p class="fine-print"><strong>Proof ${i+1} · NO COVERING NODE IN THIS MODEL</strong> — policy <span class="mono">${esc(p.policy)}</span>: ${why}. A real registry carries that case on a node this list does not contain (its origin or terminal node) — deployment data this model does not invent, so no proof is planned for this policy here.</p>`;
    }).join('');
    return `<span class="mini-label">REGISTRY PROOF PLAN · LOCAL MODEL · ${plan.registeredCount} REGISTERED · ${plan.unregisteredCount} NOT REGISTERED · ${plan.unprovableCount} WITHOUT A COVERING NODE</span>${lines}<p class="fine-print">Planned locally against the list you entered — PRISM did not read a live registry, and a plan proves a policy's status only against this modeled list. A real transfer carries the canonical deployment's actual registry nodes as reference inputs: one proof per distinct policy, in lexicographic order of the policies (CIP-113, RegistryProof Requirements).</p>`;
  }
  catch(e){return `<p class="fine-print">${esc(e.message)} A list that breaks the registry's own invariants — 28-byte keys, each once, in lexicographic order — is refused here rather than planned around, because the proofs rest on exactly those invariants.</p>`;}
}
function registryProofVerifyPreview({registry='',policies='',claimed=''}={}){
  const parse=v=>String(v??'').split(/[\s,]+/).map(s=>s.trim()).filter(Boolean);
  const keys=parse(registry),queried=parse(policies);
  const lines=String(claimed??'').split('\n').map(s=>s.trim()).filter(Boolean);
  if(!lines.length)return `<p class="fine-print">Enter the proof list a transaction claims to carry — one proof per line, in the order claimed — and it is checked against the modeled registry and policies above as you type: completeness, ordering, and correctness, each position judged separately. The example loaded above is the correct list for the modeled example, so it verifies.</p>`;
  if(!queried.length)return `<p class="fine-print">Enter at least one policy ID to prove above — a proof list is complete only against the policies the transaction touches.</p>`;
  try{
    const proofs=lines.map((line,i)=>{
      const t=line.split(/[\s,]+/).filter(Boolean);
      if(t.length<4||t.length>5)throw new Error(`Claimed proof ${i+1} must name a policy ID, a proof type, a node index, and a node key, with the node's next key as an optional fifth field — ${t.length} field${t.length===1?'':'s'} given on that line.`);
      if(!/^\d+$/.test(t[2]))throw new Error(`Claimed proof ${i+1}'s node index must be a non-negative integer — ${t[2]} given, refused rather than rounded.`);
      return {policy:t[0],proofType:t[1],nodeIndex:Number(t[2]),nodeKey:t[3],nextKey:t[4]??null};
    });
    const v=verifyRegistryProofs(keys,queried,proofs);
    const describe=p=>p.proofType==='TokenExists'?`TokenExists at node ${p.nodeIndex} (key ${p.nodeKey})`:`TokenDoesNotExist at covering node ${p.nodeIndex} (key ${p.nodeKey}, next ${p.nextKey??'not stated in this model'})`;
    const lines2=v.perProof.map(p=>{
      if(p.status==='correct')return `<p class="fine-print"><strong>Policy <span class="mono">${esc(p.policy)}</span> · PROOF CORRECT</strong> — ${esc(describe(p.expected))}: type, node index, node key${p.claimed.nextKey?', and stated next key':''} all match the modeled registry.</p>`;
      if(p.status==='missing')return `<p class="fine-print"><strong>Policy <span class="mono">${esc(p.policy)}</span> · NO PROOF CLAIMED</strong> — completeness fails: the list must carry one proof for this policy, and the correct one is ${esc(describe(p.expected))}.</p>`;
      if(p.status==='unverifiable')return `<p class="fine-print"><strong>Policy <span class="mono">${esc(p.policy)}</span> · UNVERIFIABLE IN THIS MODEL</strong> — the policy ${p.expected.reason==='empty-registry'?'cannot be proved against an empty modeled registry':p.expected.reason==='before-first'?'sorts before the first key in the modeled list':'sorts after the last key in the modeled list'}, so no covering node in this list can judge a proof for it, claimed or not. A real registry carries that case on its origin or terminal node — deployment data this model does not invent.</p>`;
      const failed=[];
      if(!p.verdicts.proofType)failed.push(`proof type (claimed ${esc(p.claimed.proofType)}, correct is ${esc(p.expected.proofType)})`);
      if(!p.verdicts.nodeIndex)failed.push(`node index (claimed ${p.claimed.nodeIndex}, the node's index in this list is ${p.expected.nodeIndex})`);
      if(!p.verdicts.nodeKey)failed.push(`node key (claimed ${esc(p.claimed.nodeKey)}, correct is ${esc(p.expected.nodeKey)})`);
      if(p.verdicts.nextKey===false)failed.push(`next key (claimed ${esc(p.claimed.nextKey)}, the node's next in this list is ${p.expected.nextKey??'none — it is the last node'})`);
      return `<p class="fine-print"><strong>Policy <span class="mono">${esc(p.policy)}</span> · PROOF INCORRECT</strong> — ${failed.join('; ')}. The correct proof is ${esc(describe(p.expected))}.</p>`;
    }).join('');
    const extraLines=[
      ...v.completeness.extra.map(pol=>`<p class="fine-print"><strong>Extra proof · <span class="mono">${esc(pol)}</span></strong> — this policy is not among the policies to prove above, so completeness fails: the list must carry exactly one proof per distinct policy touched, no more.</p>`),
      ...v.completeness.duplicates.map(pol=>`<p class="fine-print"><strong>Duplicate proof · <span class="mono">${esc(pol)}</span></strong> — this policy is proved more than once; the spec requires one proof per distinct policy.</p>`),
      v.ordering.ordered?'':`<p class="fine-print"><strong>Ordering fails</strong> — claimed proof ${v.ordering.firstOutOfOrder+1} is out of place: the list order must match the policies' lexicographic ordering, whatever order the proofs were assembled in.</p>`,
    ].join('');
    return `<span class="mini-label">REGISTRY PROOF LIST · LOCAL MODEL · ${v.valid?'VALID AGAINST THIS MODEL':'NOT VALID'} · ${v.correctCount} CORRECT · ${v.incorrectCount} INCORRECT · ${v.missingCount} MISSING · ${v.unverifiableCount} UNVERIFIABLE</span>${lines2}${extraLines}<p class="fine-print">Checked locally against the modeled list above — PRISM read no live registry and inspected no transaction or reference inputs. A valid verdict proves only that this list satisfies the spec's three requirements against THIS modeled list (CIP-113, RegistryProof Requirements) — not that a real transaction carries these nodes, or that a validator accepted it.</p>`;
  }
  catch(e){return `<p class="fine-print">${esc(e.message)} Nothing is scored until every claimed proof can be read and the modeled registry satisfies its own invariants — a claimed proof that cannot be read is refused here rather than reported as a wrong proof.</p>`;}
}
function registryDiffPreview({registry='',policies='',after=''}={}){
  const parse=v=>String(v??'').split(/[\s,]+/).map(s=>s.trim()).filter(Boolean);
  const beforeKeys=parse(registry),queried=parse(policies),afterKeys=parse(after);
  if(!afterKeys.length)return `<p class="fine-print">Enter the modeled registry as it would be after the change — one policy ID per line, in lexicographic order — and the impact on each proof above appears as you type, compared locally between the two lists.</p>`;
  if(!queried.length)return `<p class="fine-print">Enter at least one policy ID to prove above — the impact is judged per policy a transfer touches.</p>`;
  try{
    const d=diffRegistryProofs(beforeKeys,afterKeys,queried);
    const describe=p=>{
      if(p.status==='registered')return `TokenExists at node ${p.nodeIndex} (key ${p.nodeKey})`;
      if(p.status==='unregistered')return `TokenDoesNotExist at covering node ${p.nodeIndex} (key ${p.nodeKey}, next ${p.nextKey})`;
      return p.reason==='empty-registry'?'no proof in this model (the list is empty)':p.reason==='before-first'?'no proof in this model (sorts before the first key)':'no proof in this model (sorts after the last key)';
    };
    const labels={'unchanged':['PROOF UNCHANGED','the proof planned against the before list is exactly the proof the after list requires'],'proof-changed':['PROOF CHANGED','the registration status is the same on both sides, but the proof itself moved'],'newly-registered':['NEWLY REGISTERED','the policy is in the after registry, so an absence proof planned before this change now fails correctness'],'no-longer-registered':['NO LONGER REGISTERED','the policy is not in the after registry, so an existence proof planned before this change names a node that is no longer its proof'],'newly-provable':['NEWLY PROVABLE','the before list carried no covering node for this policy; the after list does'],'newly-unprovable':['NEWLY UNPROVABLE','the before list could prove this policy; the after list carries no covering node for it']};
    const lines=d.perPolicy.map(p=>{
      const pair=labels[p.change];
      const fields=p.changedFields.length?` Changed positions: ${p.changedFields.join(', ')}.`:'';
      return `<p class="fine-print"><strong>Policy <span class="mono">${esc(p.policy)}</span> · ${pair[0]}</strong> — before: ${esc(describe(p.before))}; after: ${esc(describe(p.after))}.${fields} ${pair[1]}.</p>`;
    }).join('');
    const keyLines=[
      d.addedKeys.length?`<p class="fine-print"><strong>Keys added in the after list</strong> — ${d.addedKeys.map(k=>`<span class="mono">${esc(k)}</span>`).join(', ')}.</p>`:'',
      d.removedKeys.length?`<p class="fine-print"><strong>Keys removed in the after list</strong> — ${d.removedKeys.map(k=>`<span class="mono">${esc(k)}</span>`).join(', ')}.</p>`:'',
    ].join('');
    return `<span class="mini-label">REGISTRY CHANGE IMPACT · LOCAL MODEL · ${d.beforeSize} → ${d.afterSize} KEYS · ${d.addedKeys.length} ADDED · ${d.removedKeys.length} REMOVED · ${d.unchangedCount} OF ${d.queriedCount} PROOFS UNCHANGED</span>${keyLines}${lines}<p class="fine-print">Compared locally between the two modeled lists you entered — PRISM read no live registry, and neither list is one. An unchanged verdict means the proof planned against the before list still satisfies the after list; any other verdict means a proof list planned before the change must be re-planned for that policy before a transaction carries it (CIP-113, RegistryProof Requirements).</p>`;
  }
  catch(e){return `<p class="fine-print">${esc(e.message)} Either list breaking the registry invariants — 28-byte keys, each once, in lexicographic order — is refused here rather than diffed around, because the proofs rest on exactly those invariants.</p>`;}
}
